create function pg_temp.hu(n integer) returns uuid language sql immutable as $$select ('20200000-0000-4000-8000-'||lpad(to_hex(n),12,'0'))::uuid$$;
create function pg_temp.hrun(q text,c text default '',r text default 'postgres') returns jsonb language plpgsql as $$declare v jsonb;d text;begin perform set_config('request.jwt.claims',c,true);execute format('set local role %I',r);begin execute q into v;exception when others then get stacked diagnostics d=pg_exception_detail;v:=jsonb_build_object('error',sqlstate,'detail',d);end;set local role postgres;perform set_config('request.jwt.claims','',true);return coalesce(v,'null'::jsonb);end$$;
create function pg_temp.hg(g text,t text,f date,z date,w jsonb,m integer) returns jsonb language sql as $$select pg_temp.hrun(format('select coalesce(to_jsonb(array_agg(starts_at)),''[]''::jsonb) from app.pt_availability_grid(%L,%L,%L::date,%L::date,%L::jsonb,%L::integer)',g,t,f,z,w,m))$$;
create function pg_temp.hs(n integer default 201) returns text language sql as $$select jsonb_build_object('sub',pg_temp.hu(n),'role','authenticated','tenant_id',pg_temp.hu(1),'staff_id',pg_temp.hu(n),'app_role',case when n=201 then 'gym_owner' else 'trainer' end)::text$$;
create function pg_temp.hm(n integer default 100) returns text language sql as $$select jsonb_build_object('sub',pg_temp.hu(1000+n),'role','authenticated','tenant_id',pg_temp.hu(1),'member_id',pg_temp.hu(n),'app_role','member')::text$$;
